package com.oms.order.service;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
/** Sales parent snapshots are separate from physical component fulfillment lines. */
final class OrderBundles {
 private OrderBundles(){}
 static long coefficient(Map<String,Object> row){long q=number(row,"component_quantity");require(q>0,"套装组件配比缺失，不能继续处理");return q;}
 @SuppressWarnings("unchecked") static Map<String,Object> object(Object raw){if(raw==null)return Collections.emptyMap();if(raw instanceof Map)return (Map<String,Object>)raw;try{return JSON.readValue(raw.toString(),Map.class);}catch(Exception e){throw new IllegalArgumentException("套装快照无法读取");}}
 @SuppressWarnings("unchecked") static Map<String,Object> snapshot(String sku,String name,Map<String,Object> goods){Map<String,Object> definition=object(goods.get("bundle"));require(number(definition,"enabled")==1&&number(definition,"revision")>0&&definition.get("components") instanceof List,"套装组成未发布或已停用："+sku);List<Map<String,Object>> components=(List<Map<String,Object>>)definition.get("components");require(!components.isEmpty()&&components.size()<=50,"套装组成须为1至50种组件");Set<String> seen=new HashSet<>();for(Map<String,Object> child:components)require(!text(child,"sku_sn").isEmpty()&&!sku.equals(text(child,"sku_sn"))&&seen.add(text(child,"sku_sn"))&&number(child,"quantity")>0,"套装组件无效或重复");Map<String,Object> result=new LinkedHashMap<>(definition);result.put("sku_sn",sku);result.put("goods_name",name);return result;}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> expand(List<Map<String,Object>> lines){List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> source:lines){Map<String,Object> kit=object(source.get("bundle_snapshot"));if(kit.isEmpty()){result.add(source);continue;}if(OrderLuckyBags.lucky(kit)){result.addAll(OrderLuckyBags.expand(source,kit));continue;}if("STOCKED".equals(kit.get("inventory_mode"))){Map<String,Object> line=new LinkedHashMap<>(source);line.put("sku_sn",kit.get("sku_sn"));line.put("goods_name",kit.get("goods_name"));line.put("stocked_bundle_snapshot",kit);line.remove("bundle_snapshot");result.add(line);continue;}long units=number(source,"quantity");for(Map<String,Object> child:(List<Map<String,Object>>)kit.get("components")){Map<String,Object> line=new LinkedHashMap<>(source);line.put("sku_sn",child.get("sku_sn"));line.put("goods_name",child.get("goods_name"));line.put("quantity",Math.multiplyExact(units,number(child,"quantity")));require(number(line,"quantity")<=100000000,"套装组件需求超过单行上限");line.put("component_quantity",child.get("quantity"));line.put("bundle_quantity",units);line.put("bundle_sku",kit.get("sku_sn"));line.put("bundle_name",kit.get("goods_name"));line.put("bundle_payment",source.get("payment"));line.put("payment",java.math.BigDecimal.ZERO);result.add(line);}}require(result.size()<=500,"套装展开后超过500行，请调整订单范围");return result;}
 static Long persist(OrderRepository r,String c,long order,Map<String,Object> line){Map<String,Object> kit=object(line.get("bundle_snapshot"));if(kit.isEmpty()||"STOCKED".equals(kit.get("inventory_mode")))return null;r.db().update("INSERT IGNORE INTO oms_order_bundle(company_code,order_id,platform_oid,stock_reference,gift_plan_id,sku_sn,goods_name,quantity,payment,revision,snapshot,business_type) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",c,order,line.get("platform_oid"),text(line,"stock_reference"),line.get("gift_plan_id"),kit.get("sku_sn"),kit.get("goods_name"),line.get("bundle_quantity"),line.get("bundle_payment"),kit.get("revision"),encode(kit),OrderLuckyBags.lucky(kit)?"LUCKY_BAG":"BUNDLE");return r.db().queryForObject("SELECT id FROM oms_order_bundle WHERE company_code=? AND order_id=? AND platform_oid=? AND stock_reference=?",Long.class,c,order,line.get("platform_oid"),text(line,"stock_reference"));}

 static List<Map<String,Object>> report(OrderRepository r,String c,long order){List<Map<String,Object>> parents=r.db().query("SELECT * FROM oms_order_bundle WHERE company_code=? AND order_id=? ORDER BY id",ROW,c,order);if(parents.isEmpty())return parents;List<Map<String,Object>> lines=r.db().query("SELECT l.*,(SELECT COALESCE(SUM(s.shipped_quantity),0) FROM oms_order_shipment_line s WHERE s.company_code=l.company_code AND s.order_line_id=l.id) shipped_quantity FROM oms_order_line l WHERE l.company_code=? AND l.order_id=? AND l.bundle_id IS NOT NULL ORDER BY l.id",ROW,c,order);Map<Long,Long> luckyShipped=new HashMap<>();if(parents.stream().anyMatch(p->"LUCKY_BAG".equals(text(p,"business_type"))))for(Map<String,Object> q:r.db().query("SELECT stock_source_id,COALESCE(SUM(shipped_quantity),0) quantity FROM oms_order_shipment_line WHERE company_code=? AND shipment_id IN (SELECT id FROM oms_order_shipment WHERE company_code=? AND order_id=?) AND stock_source_id IS NOT NULL GROUP BY stock_source_id",ROW,c,c,order))luckyShipped.put(number(q,"stock_source_id"),number(q,"quantity"));for(Map<String,Object> parent:parents){List<Map<String,Object>> children=new ArrayList<>();long complete=number(parent,"quantity"),pieces=0,shipped=0;for(Map<String,Object> line:lines)if(number(line,"bundle_id")==number(parent,"id")){children.add(line);if(!"LUCKY_BAG".equals(text(parent,"business_type")))complete=Math.min(complete,number(line,"shipped_quantity")/coefficient(line));pieces+=number(line,"quantity");shipped+=number(line,"shipped_quantity");}parent.put("components",children);parent.put("shipped_sets",children.isEmpty()?0:complete);parent.put("component_quantity",pieces);parent.put("shipped_component_quantity",shipped);if("LUCKY_BAG".equals(text(parent,"business_type")))OrderLuckyBags.decorateSources(parent,luckyShipped);parent.remove("snapshot");}Map<Long,Long> returned=new HashMap<>();for(Map<String,Object> q:r.db().query("SELECT uc.unit_id,uc.refund_id FROM oms_refund_lucky_unit_claim uc JOIN oms_order_bundle b ON b.company_code=uc.company_code AND b.id=uc.bundle_id WHERE b.company_code=? AND b.order_id=?",ROW,c,order))returned.put(number(q,"unit_id"),number(q,"refund_id"));for(Map<String,Object> parent:parents)if(OrderLuckyBags.lucky(parent))for(Map<String,Object> unit:com.oms.common.lucky.LuckyBagRules.rows(parent.get("units")))if(returned.containsKey(number(unit,"unit_id")))unit.put("return_refund_id",returned.get(number(unit,"unit_id")));return parents;}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> shippingGoods(OrderRepository r,String c,long order,long packageId,Map<String,Long> goods){List<Map<String,Object>> kits=r.db().query("SELECT id,platform_oid,sku_sn,quantity,business_type,snapshot FROM oms_order_bundle WHERE company_code=? AND order_id=? ORDER BY id",ROW,c,order);if(kits.isEmpty())return Collections.emptyList();Map<String,Long> enrolled=new HashMap<>();for(Map<String,Object> task:r.db().query("SELECT payload_json FROM oms_order_platform_shipping_task WHERE company_code=? AND order_id=?",ROW,c,order)){Map<String,Object> saved=object(object(task.get("payload_json")).get("goods"));for(String oid:saved.keySet())enrolled.merge(oid,number(saved,oid),Long::sum);}List<Map<String,Object>> components=r.db().query("SELECT ol.bundle_id,ol.id,ol.sku_sn,ol.component_quantity,COALESCE(SUM(pl.quantity),0) packed FROM oms_order_line ol LEFT JOIN oms_order_shipment_line sl ON sl.company_code=ol.company_code AND sl.order_line_id=ol.id LEFT JOIN oms_order_shipment_package_line pl ON pl.company_code=sl.company_code AND pl.shipment_line_id=sl.id AND pl.package_id<=? WHERE ol.company_code=? AND ol.order_id=? AND ol.bundle_id IS NOT NULL GROUP BY ol.id,ol.bundle_id,ol.sku_sn,ol.component_quantity",ROW,packageId,c,order);Map<Long,Long> packedSources=new HashMap<>();if(kits.stream().anyMatch(p->"LUCKY_BAG".equals(text(p,"business_type"))))for(Map<String,Object> q:r.db().query("SELECT sl.stock_source_id,COALESCE(SUM(pl.quantity),0) quantity FROM oms_order_shipment_line sl JOIN oms_order_shipment_package_line pl ON pl.company_code=sl.company_code AND pl.shipment_line_id=sl.id WHERE sl.company_code=? AND sl.shipment_id IN (SELECT id FROM oms_order_shipment WHERE company_code=? AND order_id=?) AND pl.package_id<=? AND sl.stock_source_id IS NOT NULL GROUP BY sl.stock_source_id",ROW,c,c,order,packageId))packedSources.put(number(q,"stock_source_id"),number(q,"quantity"));List<Map<String,Object>> progress=new ArrayList<>();for(Map<String,Object> kit:kits){String oid=text(kit,"platform_oid");if(!goods.containsKey(oid))continue;long complete=number(kit,"quantity");boolean found=false;Map<String,Long> luckyPacked=new HashMap<>();for(Map<String,Object> part:components)if(number(part,"bundle_id")==number(kit,"id")){found=true;if("LUCKY_BAG".equals(text(kit,"business_type")))luckyPacked.merge(text(part,"sku_sn"),number(part,"packed"),Long::sum);else complete=Math.min(complete,number(part,"packed")/coefficient(part));}if("LUCKY_BAG".equals(text(kit,"business_type")))complete=OrderLuckyBags.completeSources(object(kit.get("snapshot")),packedSources);require(found,"套装组件快照缺失");long previous=enrolled.getOrDefault(oid,0L);require(previous<=number(kit,"quantity"),"套装平台回传套数超过购买数量");goods.remove(oid);long increment=Math.max(0,complete-previous);if(increment>0)goods.put(oid,increment);Map<String,Object> row=new LinkedHashMap<>(kit);row.remove("snapshot");row.put("packaged_sets",complete);row.put("sales_increment",increment);row.put("pending_sets",number(kit,"quantity")-complete);progress.add(row);}return progress;}
}
